  ,,  ,,    ,,  ,,  ,,,,    ,,,,          ,,    ,,,,    ,,
      t,t,t,                t,            t,    t,  t,vv
      ,,,,,,                ,,            ,,    ,,  ,,vv
                    t,  AAAAAAAA            t,  t,t,t,u;t,t,
                    ,,  AAAAAAAA            ,,  ,,,,,,;;,,,,
    t,                  AAAAAAAA  n t,n t,n   n t,n   vv
    ,,                  AAAAAAAA    ,,  ,,      ,,    vv
      t,            t,  AAAAAAAAt,t,t,t,  t,t,t,t,  t,vv  t,
      ,,            ,,  AAAAAAAA,,,,,,,,  ,,,,,,,,  ,,vv  ,,
